auth.probe_js:
// Stack Exchange states it itself: StackExchange.options.user, written inline by StackExchange.init().
// Do NOT gate on cookies here — the session cookies (prov, acct, the per-site auth cookie) are
// HttpOnly, so document.cookie reports a live session as logged out. Do NOT gate on `fkey` either:
// an ANONYMOUS page carries an fkey too (it is the request-forgery key, not a session).
const u = (() => { try { return (window.StackExchange && StackExchange.options && StackExchange.options.user) || null; } catch (e) { return null; } })();
if (u && (u.userId || u.isRegistered === true)) {
  const link = document.querySelector('a.my-profile, .s-topbar--item[href^="/users/"]');
  const name = link ? ((link.getAttribute('aria-label') || link.textContent || '').trim().split('\n')[0]) : '';
  return {signed_in:true, as: name || (u.userId ? 'userId:' + u.userId : undefined)};
}
if (u && (u.isAnonymous === true || u.isRegistered === false)) {
  return {signed_in:false, why:'StackExchange.options.user says anonymous'};
}
// No config object at all: an edge-cached shell, or a route that never runs StackExchange.init.
// /users/current follows through to the signed-in user's own profile; anonymous gets 404.
try {
  const r = await fetch('/users/current', {credentials:'include', redirect:'follow'});
  const m = (r.url || '').match(/\/users\/(\d+)\/([^/?#]+)/);
  if (r.status === 200 && m) return {signed_in:true, as: decodeURIComponent(m[2])};
  return {signed_in:false, why:'no StackExchange.options.user; /users/current gave ' + r.status};
} catch (e) { return {signed_in:false, why:'no user config and /users/current failed: ' + e.message}; }
